    /// moved out of a decorated subclass.
    ///
    /// A decorated subclass that extends a base class is split into an inner
    /// class (which keeps the real `extends Base`) and an outer wrapper class
    /// (which extends the `identity` helper). Static members that reference the
    /// class instance private state are relocated onto the wrapper class, so any
    /// `super.foo` they contain would resolve against `identity.prototype`
    /// instead of `Base`. Rewriting turns `super.foo` into
    /// `_get(_get_prototype_of(_Derived), "foo", this)`, i.e. a prototype-chain
    /// lookup against the decorated class reference, so parent members resolve
    /// correctly at runtime.
    fn rewrite_super_for_moved_static_node<N>(&self, node: &mut N, class_name: &Ident)
    where
        N: VisitMutWith<SuperFieldAccessFolder<'static>>,
    {
        // `SuperFieldAccessFolder` only borrows `class_name`/`super_class` for
        // the duration of the visit, so the `'static` bound on `N` is a
        // formality that lets us reuse a single generic implementation for
        // functions, expressions and statements.
        let no_super_class = None;
        let mut folder = SuperFieldAccessFolder {
            class_name,
            constructor_this_mark: None,
            is_static: true,
            folding_constructor: false,
            in_nested_scope: false,
            in_injected_define_property_call: false,
            this_alias_mark: None,
            constant_super: false,
            super_class: &no_super_class,
            in_pat: false,
        };

        node.visit_mut_with(&mut folder);
    }

    fn rewrite_super_for_moved_static_member(&self, function: &mut Function, class_name: &Ident) {
        self.rewrite_super_for_moved_static_node(function, class_name);
    }

    fn rewrite_super_for_moved_static_expr(&self, expr: &mut Expr, class_name: &Ident) {
        self.rewrite_super_for_moved_static_node(expr, class_name);
    }

